var _ = fmt.Sprint

func isAsciiDigitNavaid(b byte) bool {
	return b >= '0' && b <= '9'
}

// compareNaturalNavaid compares two strings in natural alphanumeric order (e.g. "BOR2" < "BOR10").
func compareNaturalNavaid(a, b string) int {
	sa := strings.ToUpper(strings.TrimSpace(a))
	sb := strings.ToUpper(strings.TrimSpace(b))
	ia, ib := 0, 0
	for ia < len(sa) && ib < len(sb) {
		ca, cb := sa[ia], sb[ib]
		if isAsciiDigitNavaid(ca) && isAsciiDigitNavaid(cb) {
			za, zb := ia, ib
			for ia < len(sa) && sa[ia] == '0' {
				ia++
			}
			for ib < len(sb) && sb[ib] == '0' {
				ib++
			}
			startA, startB := ia, ib
			for ia < len(sa) && isAsciiDigitNavaid(sa[ia]) {
				ia++
			}
			for ib < len(sb) && isAsciiDigitNavaid(sb[ib]) {
				ib++
			}
			lenA := ia - startA
			lenB := ib - startB
			if lenA != lenB {
				return lenA - lenB
			}
			if cmp := strings.Compare(sa[startA:ia], sb[startB:ib]); cmp != 0 {
				return cmp
			}
			if (ia - za) != (ib - zb) {
				return (ia - za) - (ib - zb)
			}
			continue
		}
		if ca != cb {
			if ca < cb {
				return -1
			}
			return 1
		}
		ia++
		ib++
	}
	return len(sa) - len(sb)
}

// navaidFirstLetter returns the leading alphabetical bucket ("A".."Z", "0-9", or "#").
func navaidFirstLetter(shortName string) string {
	s := strings.ToUpper(strings.TrimSpace(shortName))
	if strings.HasPrefix(s, "UUID.") || strings.HasPrefix(s, "URN:UUID:") {
		return "#"
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= 'A' && c <= 'Z' {
			return string(c)
		}
		if c >= '0' && c <= '9' {
			return "0-9"
		}
	}
	return "#"
}

func compareNavaidLetterKeys(a, b string) int {
	if a == b {
		return 0
	}
	if a == "#" {
		return 1
	}
	if b == "#" {
		return -1
	}
	if a == "0-9" {
		return 1
	}
	if b == "0-9" {
		return -1
	}
	return strings.Compare(a, b)
}

func navaidCategoryInfo(group navaidDomainGroup, catCode string) (order int, title string) {
	upper := strings.ToUpper(strings.TrimSpace(catCode))
	switch group {
	case groupNavaidSystems:
		switch upper {
		case "VOR_DME":
			return 10, "[VOR_DME] VOR/DME Composite System"
		case "VORTAC":
			return 12, "[VORTAC] VORTAC Composite System"
		case "VOR":
			return 14, "[VOR] VHF Omnidirectional Range System"
		case "DME":
			return 16, "[DME] Distance Measuring System"
		case "TACAN":
			return 18, "[TACAN] Tactical Air Navigation System"
		case "ILS":
			return 20, "[ILS] Instrument Landing System"
		case "ILS_DME":
			return 21, "[ILS_DME] ILS with Associated DME"
		case "MLS":
			return 24, "[MLS] Microwave Landing System"
		case "MLS_DME":
			return 25, "[MLS_DME] MLS with Associated DME"
		case "LOC":
			return 26, "[LOC] Localizer-Only System"
		case "LOC_DME":
			return 27, "[LOC_DME] Localizer/DME System"
		case "NDB":
			return 30, "[NDB] Non-Directional Beacon System"
		case "NDB_DME":
			return 31, "[NDB_DME] NDB/DME System"
		case "NDB_MKR":
			return 32, "[NDB_MKR] Compass Locator / Marker"
		case "MKR":
			return 35, "[MKR] Marker Beacon System"
		case "DF":
			return 40, "[DF] Direction Finding System"
		default:
			return 90, fmt.Sprintf("[%s] Navaid System", upper)
		}

	case groupRadioEquipment:
		switch upper {
		case "DVOR":
			return 10, "[DVOR] Doppler VOR Equipment"
		case "VOR":
			return 12, "[VOR] Conventional VOR Equipment"
		case "VTAC":
			return 14, "[VTAC] VORTAC VOR Equipment"
		case "DME":
			return 20, "[DME] DME Transponder Equipment"
		case "TACAN":
			return 25, "[TACAN] TACAN Transponder Equipment"
		case "NDB":
			return 30, "[NDB] NDB Transmitter Equipment"
		case "VDF":
			return 40, "[VDF] VHF Direction Finder"
		case "LORAN":
			return 50, "[LORAN] LORAN Navigation System"
		case "DECCA":
			return 52, "[DECCA] DECCA Navigation System"
		case "GNSS":
			return 54, "[GNSS] GNSS Augmentation System"
		default:
			return 90, fmt.Sprintf("[%s] Radio Navaid Equipment", upper)
		}

	case groupApproachGuidance:
		switch upper {
		case "LLZ":
			return 10, "[LLZ] ILS Localizer"
		case "GP":
			return 20, "[GP] ILS Glidepath"
		case "OUTER":
			return 30, "[OUTER] Outer Marker Beacon"
		case "MIDDLE":
			return 31, "[MIDDLE] Middle Marker Beacon"
		case "INNER":
			return 32, "[INNER] Inner Marker Beacon"
		case "BACK":
			return 33, "[BACK] Back-Course Marker Beacon"
		case "FAN":
			return 34, "[FAN] Enroute / Fan Marker Beacon"
		case "MKR":
			return 35, "[MKR] Marker Beacon"
		case "SDF":
			return 40, "[SDF] Simplified Directional Facility"
		case "MLS_AZ":
			return 50, "[MLS_AZ] MLS Azimuth Guidance"
		case "MLS_EL":
			return 52, "[MLS_EL] MLS Elevation Guidance"
		default:
			return 90, fmt.Sprintf("[%s] Approach Guidance Aid", upper)
		}

	case groupWaypoints:
		switch upper {
		case "ICAO":
			return 10, "[ICAO] 5-Letter ICAO Waypoint"
		case "ADHP":
			return 15, "[ADHP] Terminal / Aerodrome Waypoint"
		case "COORD":
			return 20, "[COORD] Geographical Coordinate Fix"
		case "CNF":
			return 25, "[CNF] Computer Navigation Fix"
		case "DESIGNED":
			return 28, "[DESIGNED] Procedure Waypoint"
		case "OTHER", "WPT":
			return 35, fmt.Sprintf("[%s] Designated Reporting Point", upper)
		case "ENTRY_EXIT":
			return 50, "[ENTRY_EXIT] Airspace Entry/Exit Point"
		case "ENTRY":
			return 51, "[ENTRY] Airspace Entry Point"
		case "EXIT":
			return 52, "[EXIT] Airspace Exit Point"
		case "BORDER", "FIR_BDRY":
			return 55, fmt.Sprintf("[%s] Airspace Boundary Point", upper)
		default:
			return 90, fmt.Sprintf("[%s] Airspace / Waypoint Fix", upper)
		}

	case groupIndications:
		switch upper {
		case "RDL":
			return 10, "[RDL] VOR Radial Indication"
		case "BRG":
			return 15, "[BRG] Magnetic Bearing Indication"
		case "TRK":
			return 20, "[TRK] Track Indication"
		case "DME", "DME_IND":
			return 30, "[DME] DME Slant-Range Distance"
		case "DIST":
			return 35, "[DIST] Geodesic Distance Indication"
		case "GNSS":
			return 40, "[GNSS] GNSS RNAV Distance Indication"
		default:
			return 90, fmt.Sprintf("[%s] Bearing / Distance Indication", upper)
		}

	case groupCheckpointsAndRadars:
		switch upper {
		case "RADAR_TAR":
			return 10, "[RADAR_TAR] Terminal Approach Radar System"
		case "RADAR_ARSR":
			return 11, "[RADAR_ARSR] Enroute Surveillance Radar System"
		case "RADAR_ASR":
			return 12, "[RADAR_ASR] Airport Surveillance Radar System"
		case "RADAR":
			return 15, "[RADAR] Surveillance Radar System"
		case "PSR", "PSR_ENR", "PSR_TAR":
			return 20, fmt.Sprintf("[%s] Primary Surveillance Radar", upper)
		case "SSR_MODE_S", "SSR_S":
			return 25, fmt.Sprintf("[%s] Mode-S Secondary Surveillance Radar", upper)
		case "SSR", "SSR_A", "SSR_C", "SSR_A_C":
			return 26, fmt.Sprintf("[%s] Secondary Surveillance Radar", upper)
		case "PAR":
			return 30, "[PAR] Precision Approach Radar"
		case "CHK_VOR_G":
			return 40, "[CHK_VOR_G] Ground VOR Calibration Checkpoint"
		case "CHK_VOR_A":
			return 41, "[CHK_VOR_A] Airborne VOR Calibration Checkpoint"
		case "CHK_VOR":
			return 42, "[CHK_VOR] VOR Calibration Checkpoint"
		case "CHK_INS":
			return 50, "[CHK_INS] Apron INS / GNSS Calibration Stand"
		default:
			return 90, fmt.Sprintf("[%s] Checkpoint / Radar Facility", upper)
		}
	}
	return 99, fmt.Sprintf("[%s] Feature", upper)
}

func (stager *Stager) isNavaidGroupExpanded(group navaidDomainGroup) bool {
	switch group {
	case groupNavaidSystems:
		return stager.isNavaidSystemsExpanded
	case groupRadioEquipment:
		return stager.isRadioEquipmentExpanded
	case groupApproachGuidance:
		return stager.isApproachGuidanceExpanded
	case groupWaypoints:
		return stager.isWaypointsExpanded
	case groupIndications:
		return stager.isIndicationsExpanded
	case groupCheckpointsAndRadars:
		return stager.isCheckpointsAndRadarsExpanded
	default:
		return true
	}
}

